INSERT INTO generations (id, projectId, promptId, promptText, negativePrompt, parameters, resultImageUrl, resultImageKey, status, qualityScore, faceConsistencyScore, reviewNotes, stage, upscaledImageUrl, upscaledImageKey, generationTimeMs, merchandiseFormat, outputWidth, outputHeight, createdAt, updatedAt) VALUES (1380011, 420001, NULL, '야외 공원에서 찍은 동아시아 여성의 밝고 명랑한 셀카 사진입니다. 40대 여성은 따뜻한 언더톤의 하얀 피부에 부드러운 미소를 짓고 있으며, 직접적으로 눈맞춤을 하고 있습니다. 또한 여성은 평화의 손짓을 하고 있으며, 흰색의 얇고 긴 소매에 단추가 달린 블라우스를 입고 있습니다. 블라우스 소매 끝에는 주름 장식이 있으며, 여성은 갈색 숄더백을 메고 있습니다. 자연광은 밝은 주간광으로 부드러운 방향성을 띠며 부드러운 그림자와 차가운 색온도를 만들어 낸다. 배경에는 무성한 녹색 나무, 먼 언덕, 현대식 건물, 맑은 푸른 하늘이 담겨 있으며 모두 얕은 심도와 부드러운 원형 보케로 인해 부드럽고 흐릿하게 처리되었다. 구도는 클로즈업과 눈높이 샷을 활용하여 삼분할 법칙을 적용한 것으로, 자연스럽고 평온하며 낙관적인 분위기를 전달합니다. 이미지는 생생한 블루와 따뜻한 피부 톤, 높은 밝기, 중간 정도의 채도를 가진 자연스러운 색상 그레이딩이 적용되었으며, 스마트폰으로 촬영되었습니다.', 'blurry, out of focus, low resolution, grainy, distorted, bad anatomy, ugly, deformed, extra limbs, bad hands, dark, gloomy, oversaturated, monochromatic, grayscale, artificial lighting, indoor setting, messy background, unnatural expression, aggressive, sad, angry, text, watermark, signature, multiple subjects, crowded, poor lighting, low contrast.', '{"faceFixMode":true}', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663303025775/XqpmVNg2gXVc63dygihuzB/generated/1772777888310.png', NULL, 'completed', NULL, 95, NULL, 'draft', NULL, NULL, 8998, NULL, NULL, NULL, '2026-03-06 11:17:59', '2026-03-06 11:18:08');
