INSERT INTO generations (id, projectId, promptId, promptText, negativePrompt, parameters, resultImageUrl, resultImageKey, status, qualityScore, faceConsistencyScore, reviewNotes, stage, upscaledImageUrl, upscaledImageKey, generationTimeMs, merchandiseFormat, outputWidth, outputHeight, createdAt, updatedAt) VALUES (1380013, 420001, NULL, '젊은 아시아 여성의 밝고 섹시미 넘치는사진으로, 광각 렌즈와 얕은 심도로 촬영되어 부드러운 보케 효과를 연출했습니다. 그녀는 건강하게 빛나는 고운 피부와 은은한 홍조를 띠고 있으며, 상냥한 미소와 친근한 직시 눈빛을 보여줍니다. 표정은 유쾌하고 낙관적입니다. 러플 소매가 달린 심플한 레드색 긴팔 라운드 실크 블라우스와 작은 진주 귀걸이를 착용했으며, 오른손으로 평화 사인을 하고 있습니다. 조명은 자연스럽고 밝은 정면 채광의 햇빛으로 따뜻한 색온도를 띠며 부드러운 그림자를 드리운다. 배경은 어두운 블랙공간으로 화려한 조명이 비치는 웅장한 공간으로 부드럽고 은은하게 처리되었다. 전체적인 분위기는 행복하고 평화로우며 상쾌하며, 생동감 넘치는 자연스러운 색감과 하이키 미학을 보여준다. 구도는 균형 잡혔으며 피사체가 약간 중심에서 벗어나 있어 차분함과 자신감을 전달한다.', 'blurry, out of focus, distorted, gloomy, dark, sad, angry, messy background, poor lighting, low resolution, bad anatomy, extra limbs, dull colors, oversaturated, unnatural skin, wrinkles, blemishes, bad quality, unappealing, disfigured, text, watermark, signature, multiple people, indoor, night, rain, heavy makeup, aggressive expression', '{"faceFixMode":true}', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663303025775/XqpmVNg2gXVc63dygihuzB/generated/1772778691193.png', NULL, 'completed', NULL, 95, NULL, 'draft', NULL, NULL, 11438, NULL, NULL, NULL, '2026-03-06 11:31:19', '2026-03-06 11:31:31');
